import { WasteCountry, WasteRecyclingData } from '@eco-metrics/shared';

import { WasteRecyclingService } from '../../src/modules/waste-recycling/waste-recycling.service';

/** Invariants of the committed dataset generated by `scripts/generate-waste-recycling-data.mjs`. */
describe('WasteRecyclingService over the real dataset', () => {
  const service = new WasteRecyclingService();
  const { world, countries }: WasteRecyclingData = service.getData();
  const byCode = (code: string): WasteCountry => {
    const found = countries.find((country) => country.code === code);
    if (!found) {
      throw new Error(`${code} is not in the dataset`);
    }
    return found;
  };
  const sumTenths = (shares: Record<string, number | null>): number =>
    Math.round(Object.values(shares).reduce<number>((sum, share) => sum + (share ?? 0), 0) * 10);

  it('should record the source update date and the retrieval date', () => {
    expect(service.getDates()).toEqual({ lastUpdated: '2026-03-11', retrieved: '2026-11-11' });
  });

  it('should hold the 217 countries, sorted by name with unique codes', () => {
    const names = countries.map(({ name }) => name);

    expect(countries).toHaveLength(217);
    expect(names).toEqual([...names].sort((a, b) => a.localeCompare(b, 'en')));
    expect(new Set(countries.map(({ code }) => code)).size).toBe(217);
  });

  it('should sum every reported treatment and composition to exactly 100.0', () => {
    const grouped = countries.flatMap(({ treatment, composition }) =>
      [treatment, composition].filter((value) => value !== undefined),
    );

    expect(grouped.length).toBeGreaterThan(300);
    expect(grouped.every(({ shares }) => sumTenths(shares) === 1000)).toBe(true);
  });

  it('should leave a group null rather than zero where the workbook is blank', () => {
    const china = byCode('CHN').treatment?.shares;
    const india = byCode('IND').treatment?.shares;

    expect(china?.recycling).toBeNull();
    expect(india?.recycling).toBeNull();
    expect(byCode('ARG').treatment?.shares.recycling).toBeNull();
    expect(byCode('BRA').treatment?.shares.composting).toBeNull();
    expect(byCode('BRA').treatment?.shares.recycling).toBeGreaterThan(0);
  });

  it('should never report a treatment or composition without a reported group', () => {
    const reported = countries.flatMap(({ treatment, composition }) =>
      [treatment, composition].filter((value) => value !== undefined),
    );

    expect(
      reported.every(({ shares }) => Object.values(shares).some((share) => share !== null)),
    ).toBe(true);
  });

  it('should report Germany at 1.63 kg per person per day in 2022', () => {
    const germany = byCode('DEU');

    expect(germany.generation).toMatchObject({ kgPerPersonPerDay2022: 1.63, reportedYear: 2022 });
    expect(germany.generation.tonnes2030).toBeGreaterThan(0);
    expect(germany.treatment?.shares.recycling).toBeCloseTo(47, 0);
    expect(germany.treatment?.shares.composting).toBeCloseTo(22, 0);
    expect(germany.treatment?.shares.incineration).toBeCloseTo(29.5, 0);
  });

  it('should keep China without recycling and with about 75 % incineration', () => {
    expect(byCode('CHN').treatment?.shares.incineration).toBeCloseTo(75, 0);
  });

  it('should normalize Bolivia, whose reported shares add up to more than 100 %', () => {
    expect(sumTenths(byCode('BOL').treatment?.shares ?? {})).toBe(1000);
  });

  it('should give India a composition and Nigeria no treatment', () => {
    expect(byCode('IND').composition).toBeDefined();
    expect(byCode('NGA').treatment).toBeUndefined();
  });

  it('should date Albania treatment 2022 from its latest codebook row', () => {
    expect(byCode('ALB').treatment?.year).toBe(2022);
  });

  it('should report the tonnes of Germany for 2022, 2030, 2040 and 2050', () => {
    const { tonnes2022, tonnes2030, tonnes2040, tonnes2050 } = byCode('DEU').generation;

    expect([tonnes2022, tonnes2030, tonnes2040, tonnes2050].every((tonnes) => tonnes > 0)).toBe(
      true,
    );
    expect(tonnes2050).toBeGreaterThan(tonnes2030);
  });

  it('should give Germany treatment shares that sum to exactly 100', () => {
    expect(sumTenths(byCode('DEU').treatment?.shares ?? {})).toBe(1000);
  });

  it('should give India the six composition groups, each share reported or null', () => {
    const shares = byCode('IND').composition?.shares ?? {};

    expect(Object.keys(shares).sort()).toEqual([
      'foodOrganic',
      'glass',
      'metal',
      'other',
      'paperCardboard',
      'plastic',
    ]);
    expect(sumTenths(shares)).toBe(1000);
  });

  it('should count 181 countries with treatment and 179 with composition', () => {
    expect(countries.filter(({ treatment }) => treatment).length).toBe(181);
    expect(countries.filter(({ composition }) => composition).length).toBe(179);
  });

  it('should key Kosovo by its OWID entity code with the XK flag', () => {
    expect(byCode('OWID_KOS')).toMatchObject({ iso2: 'XK', name: 'Kosovo' });
  });

  it('should sum the world to about 2.33 billion tonnes in 2022 and 3.49 billion in 2050', () => {
    expect(world.generation.tonnes2022 / 1e9).toBeCloseTo(2.33, 2);
    expect(world.generation.tonnes2050 / 1e9).toBeCloseTo(3.49, 2);
    expect(world.generation.kgPerPersonPerDay2022).toBe(0.8);
    expect(world.generation.tonnes2022).toBe(
      countries.reduce((sum, { generation }) => sum + generation.tonnes2022, 0),
    );
  });

  it('should summarize recycling over the 130 countries that report it', () => {
    const reporting = countries.filter(({ treatment }) => treatment?.shares.recycling != null);

    expect(world.recycling.countries).toBe(130);
    expect(reporting).toHaveLength(130);
    expect(world.recycling.sharePercent).toBeCloseTo(17.6, 1);
    expect(world.recycling.populationSharePercent).toBeCloseTo(46.47, 2);
  });

  it('should preselect the ten most populous countries with treatment data', () => {
    const topTen = countries
      .filter(({ treatment }) => treatment)
      .sort((a, b) => (b.population ?? 0) - (a.population ?? 0))
      .slice(0, 10)
      .map(({ code }) => code);

    expect(topTen).toEqual(['CHN', 'IND', 'USA', 'IDN', 'BRA', 'BGD', 'RUS', 'MEX', 'JPN', 'ETH']);
  });
});
